package com.yeyamo_mobile.api.notification_service.infrastructure.channel;
import java.time.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.data.domain.PageRequest;import org.springframework.http.MediaType;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.client.RestClient;import com.fasterxml.jackson.databind.JsonNode;import com.yeyamo_mobile.api.notification_service.application.DevicePushTokenService;import com.yeyamo_mobile.api.notification_service.application.port.DevicePushTokenRepositoryPort;import com.yeyamo_mobile.api.notification_service.infrastructure.persistence.*;
@Component public class PushReceiptScheduler{private final SpringPushTicketRepository tickets;private final DevicePushTokenRepositoryPort devices;private final DevicePushTokenService deviceService;private final RestClient client;private final String endpoint;private final String token;public PushReceiptScheduler(SpringPushTicketRepository t,DevicePushTokenRepositoryPort d,DevicePushTokenService s,RestClient.Builder builder,@Value("${notification.push.receipts-endpoint:https://exp.host/--/api/v2/push/getReceipts}")String endpoint,@Value("${notification.push.access-token:}")String token){tickets=t;devices=d;deviceService=s;client=builder.build();this.endpoint=endpoint;this.token=token;}@Scheduled(fixedDelayString="${notification.push.receipts-delay-ms:300000}")@Transactional public void poll(){var pending=tickets.findByStatusAndReceiptCheckedAtIsNullAndCreatedAtBeforeOrderByCreatedAtAsc("ACCEPTED",Instant.now().minusSeconds(60),PageRequest.of(0,100));if(pending.isEmpty())return;RestClient.RequestBodySpec request=client.post().uri(endpoint).contentType(MediaType.APPLICATION_JSON);if(token!=null&&!token.isBlank())request.header("Authorization","Bearer "+token);JsonNode response=request.body(Map.of("ids",pending.stream().map(t->t.expoTicketId).filter(Objects::nonNull).toList())).retrieve().body(JsonNode.class);JsonNode data=response==null?null:response.path("data");Instant now=Instant.now();for(PushTicketEntity ticket:pending){JsonNode receipt=data==null?null:data.get(ticket.expoTicketId);if(receipt==null)continue;String status=text(receipt,"status");String error=text(receipt.path("details"),"error");ticket.status="ok".equals(status)?"DELIVERED":"ERROR";ticket.errorCode=error;ticket.errorMessage=text(receipt,"message");ticket.receiptCheckedAt=now;tickets.save(ticket);if("DeviceNotRegistered".equals(error))devices.findById(ticket.deviceTokenId).ifPresent(device->deviceService.invalidate(device.token()));}}private String text(JsonNode n,String field){JsonNode value=n==null?null:n.get(field);return value==null||value.isNull()?null:value.asText();}}
